ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  externalID: vars.inputPayload.documentType ++ vars.inputPayload.documentNumber,
  subscriberType: "EXTERNAL",
  document: {
    documentType: "EXTERNAL",
    fiscalID: vars.inputPayload.documentType ++ vars.inputPayload.documentNumber
  }
}

%dw 2.0
output application/json
---
{
  name: "Creating a new BillingAccount",
  externalID: vars.inputPayload.billingAccountNumber,
  subscriber: {
    id: if (isEmpty(vars.subscriberObject.content default [])) vars.postSubscriberResp.externalID else vars.subscriberObject.content[0].id
  },
  cycleConfig: {
    cycleDay: vars.inputPayload.PAM
  }
}

%dw 2.0
output application/json
---
{
  defaultBillingAccount: {
    id: if (vars.billingAccountInfo.content[0].id == null) vars.billingAccountObject.id else vars.billingAccountInfo.content[0].id,
    name: "Moving subscription to billing account cycle"
  }
}

%dw 2.0
output application/json
fun addDChar(str: String): String =
  if (str matches /^[0-9]+$/) "D" ++ str else str
var pkg = vars.omOriginal.resource.simChangePackageId default p('global.renoRepo.packageId')
---
{
  ("type"): p('jsc-sapi.order.type'),
  salesChannel: p('jsc-sapi.order.salesChannel'),
  status: p('jsc-sapi.order.status'),
  packages: [{ id: addDChar(pkg) }],
  subscription: { id: vars.subscriptionId }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
{
  (vars.orderObject),
  subscription: (vars.orderObject.subscription default {}) ++ { id: vars.orderObject.subscription.id default vars.subscriptionId },
  subscriber: (vars.orderObject.subscriber default {}) ++ { id: vars.orderObject.subscriber.id default vars.subscriberIdForPlan }
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  name: "Creating a new BillingAccount",
  subscriber: {
    id: vars.orderObject.subscriber.id default vars.subscriberIdForPlan
  },
  cycleConfig: {
    cycleDay: vars.pam
  }
}

%dw 2.0
output application/json
---
{
  billingAccount: {
    id: vars.billingAccountObject.id,
    name: "Moving subscription to billing account cycle"
  }
}

%dw 2.0
output application/json
var ext = vars.omOriginal.holder.externalId default (vars.omOriginal.holder.documentType ++ vars.omOriginal.holder.documentNumber)
---
{
  name: p('jsc-sapi.createBillingAccount.ba.name'),
  externalID: ext,
  subscriber: { id: vars.subscriberLineId },
  cycleConfig: { cycleDay: (vars.omOriginal.holder.cycleDay default "15") }
}

%dw 2.0
output application/json
---
{
  defaultBillingAccount: {
    id: vars.newBillingAccountId,
    name: p('jsc-sapi.createBillingAccount.subscription.nameMoveSubsc')
  }
}

%dw 2.0
output application/json
fun addDChar(str: String): String =
  if (str matches /^[0-9]+$/) "D" ++ str else str
var pkg = p('jsc-sapi.order.msisdnChangePackageId')
---
{
  ("type"): p('jsc-sapi.order.type'),
  salesChannel: p('jsc-sapi.order.salesChannel'),
  status: p('jsc-sapi.order.status'),
  packages: [{ id: addDChar(pkg) }],
  subscription: { id: vars.subscriptionId }
}
